return-response.set-body:
@{
                                int used  = Convert.ToInt32(context.Variables["anon-call-count"]);
                                int limit = 3;
                                return new JObject(
                                    new JProperty("used",      used),
                                    new JProperty("limit",     limit),
                                    new JProperty("remaining", Math.Max(0, limit - used)),
                                    new JProperty("allowed",   used < limit)
                                ).ToString();
                            }

when.condition:
@{
                                var jwt = (Jwt)context.Variables["jwt-token"];
                                bool hasScp = false;
                                bool hasRole = false;
                                if (jwt.Claims.ContainsKey("scp")) {
                                    string scopeString = string.Join(" ", jwt.Claims["scp"]);
                                    hasScp = scopeString.Contains("Classify.News");
                                }
                                if (jwt.Claims.ContainsKey("roles")) {
                                    string rolesString = string.Join(" ", jwt.Claims["roles"]);
                                    hasRole = rolesString.Contains("API.Classify");
                                }
                                return !(hasScp || hasRole);
                            }

return-response.set-body:
@{
                                        return new JObject(
                                            new JProperty("error", "forbidden"),
                                            new JProperty("message", "Insufficient permissions. Token must have scope 'Classify.News' or role 'API.Classify'."),
                                            new JProperty("status", 403)
                                        ).ToString();
                                    }

set-variable.value:
@{
                            var jwt = (Jwt)context.Variables["jwt-token"];
                            if (jwt.Claims.ContainsKey("oid")) { return jwt.Claims["oid"][0]; }
                            if (jwt.Claims.ContainsKey("appid")) { return jwt.Claims["appid"][0]; }
                            return "anonymous";
                        }

@{
                            var jwt = (Jwt)context.Variables["jwt-token"];
                            if (jwt.Claims.ContainsKey("preferred_username")) { return jwt.Claims["preferred_username"][0]; }
                            if (jwt.Claims.ContainsKey("appid")) { return "app-client-" + jwt.Claims["appid"][0]; }
                            return "unknown";
                        }

return-response.set-body:
@{
                                        return new JObject(
                                            new JProperty("error", "anonymous_quota_exceeded"),
                                            new JProperty("message", "You have reached the limit of 3 free analyses per day. Login with your organization account for unlimited access."),
                                            new JProperty("status", 429),
                                            new JProperty("retry_after_seconds", 86400)
                                        ).ToString();
                                    }

trace.message:
@{
                var error = context.LastError;
                var userId = context.Variables.GetValueOrDefault("user-id", "unknown");
                return $"Error: {error.Message} | User: {userId} | Source: {error.Source} | Reason: {error.Reason}";
            }

return-response.set-body:
@{
                        return new JObject(
                            new JProperty("error", "unauthorized"),
                            new JProperty("message", "Valid Azure AD JWT token required. Please authenticate."),
                            new JProperty("timestamp", DateTime.UtcNow.ToString("o")),
                            new JProperty("status", 401)
                        ).ToString();
                    }

@{
                        return new JObject(
                            new JProperty("error", "rate_limit_exceeded"),
                            new JProperty("message", "You have exceeded the allowed request limit. Please wait or login with your organization account for unlimited access."),
                            new JProperty("timestamp", DateTime.UtcNow.ToString("o")),
                            new JProperty("status", 429),
                            new JProperty("retry_after_seconds", 86400)
                        ).ToString();
                    }
